export class TokenBucket { #tokens; #updated; constructor({capacity=60,refillPerSecond=1,now=()=>Date.now()}={}){this.capacity=capacity;this.refill=refillPerSecond;this.now=now;this.#tokens=capacity;this.#updated=now();} consume(cost=1){const n=this.now();this.#tokens=Math.min(this.capacity,this.#tokens+(n-this.#updated)/1000*this.refill);this.#updated=n;if(this.#tokens<cost)return{allowed:false,retryAfterSeconds:(cost-this.#tokens)/this.refill};this.#tokens-=cost;return{allowed:true,remaining:this.#tokens};} }
